import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { BoardProps, Finished, Run, Prefs } from '../types'
import { CARETS, DEFAULT_PREFS, SIZES, tagOf } from './options.ts'

const MAX_RUNS = 5000

const round = atom({ plugin: 'monkey', key: 'round' } as const, null)
const best = atom({ plugin: 'monkey', key: 'best' } as const, null)
const record = atom({ plugin: 'monkey', key: 'record' } as const, null)
const prefs = atom({ plugin: 'monkey', key: 'prefs' } as const, DEFAULT_PREFS)

const isFinished = (data: unknown): data is Finished => {
  const d = data as Partial<Finished> | null

  return (
    typeof d?.id === 'string' &&
    typeof d.mode === 'string' &&
    typeof d.wpm === 'number' &&
    typeof d.accuracy === 'number' &&
    typeof d.seconds === 'number'
  )
}

const prefsFrom = (stored: unknown): Prefs => {
  const s = { ...DEFAULT_PREFS, ...(stored as Partial<Prefs> | undefined) }

  return {
    kind: s.kind === 'time' ? 'time' : 'words',
    words: (SIZES.words as readonly number[]).includes(s.words) ? s.words : DEFAULT_PREFS.words,
    time: (SIZES.time as readonly number[]).includes(s.time) ? s.time : DEFAULT_PREFS.time,
    caret: (CARETS as readonly string[]).includes(s.caret) ? s.caret : DEFAULT_PREFS.caret,
  }
}

const bestOf = (runs: Run[], mode: string): number | null =>
  runs.reduce<number | null>((top, run) => (run.mode === mode && run.wpm > (top ?? -1) ? run.wpm : top), null)

const runsIn = async ($: EngineInterface) => ((await $.store.get('runs')) ?? []) as Run[]

const save = async ($: EngineInterface, next: Prefs) => {
  await $.store.set('settings', next)
  await update($, prefs, () => next)
}

const startRound = async ($: EngineInterface, next: Prefs) => {
  const top = bestOf(await runsIn($), tagOf(next))
  await save($, next)
  await update($, best, () => top)
  await update($, record, () => null)
  await update($, round, current => (current ?? 0) + 1)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'monkey',
      description: 'Typing test above the prompt: words or time mode, then your WPM',
    })

    return next(e)
  })

  on('command.run', { command: 'monkey' }, async $ => {
    await startRound($, prefsFrom(await $.store.get('settings')))

    return { text: 'Typing test above the prompt: click it, then type.' }
  })

  on('ui.message', async ($, e, next) => {
    if (e.component !== 'AbovePrompt' || !isFinished(e.data)) {
      return next(e)
    }

    const { id, ...result } = e.data
    const runs = await runsIn($)
    const previous = bestOf(runs, result.mode)
    await $.store.set('runs', [...runs, { ...result, at: await $.clock.now() }].slice(-MAX_RUNS))

    if (result.mode === tagOf(await read($, prefs)) && result.wpm > (previous ?? 0)) {
      await update($, best, () => result.wpm)
      await update($, record, () => ({ id, previous }))
    }

    return {}
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const current = await read($, round)

    if (current === null || e.props.hasSurvey || e.surface === 'mobile' || e.surface === 'vscode') {
      return next(e)
    }

    const { Box, Button, Client, Text } = $.ui.resolve(e)
    const chosen = await read($, prefs)
    const size = chosen.kind === 'words' ? chosen.words : chosen.time
    const props: BoardProps = {
      kind: chosen.kind,
      size,
      caret: chosen.caret,
      best: await read($, best),
      record: await read($, record),
    }
    const choose = (change: Partial<Prefs>) => () => startRound($, { ...chosen, ...change })
    const nextCaret = CARETS[(CARETS.indexOf(chosen.caret as (typeof CARETS)[number]) + 1) % CARETS.length] ?? DEFAULT_PREFS.caret

    return (
      <Box borderStyle="round" paddingX={1} flexDirection="column">
        <Client key={`board-${current}`} module="./board.tsx" width="100%" props={props} />
        <Box key="controls" gap={1}>
          <Button key="next" label="Next" onPress={() => update($, round, () => current + 1)} />
          <Button key="close" label="Close" onPress={() => update($, round, () => null)} />
          <Text dimColor>·</Text>
          {(['words', 'time'] as const).map(kind => (
            <Button
              key={`kind-${kind}`}
              label={kind}
              variant={kind === chosen.kind ? 'primary' : undefined}
              dimColor={kind !== chosen.kind}
              onPress={choose({ kind })}
            />
          ))}
          <Text dimColor>·</Text>
          {SIZES[chosen.kind].map(option => (
            <Button
              key={`size-${option}`}
              label={String(option)}
              variant={option === size ? 'primary' : undefined}
              dimColor={option !== size}
              onPress={choose(chosen.kind === 'words' ? { words: option } : { time: option })}
            />
          ))}
          <Text dimColor>·</Text>
          <Button key="caret" label={`caret: ${chosen.caret}`} onPress={() => save($, { ...chosen, caret: nextCaret })} />
        </Box>
      </Box>
    )
  })
}

