import type { Kind, Prefs } from '../types'

export const SIZES = { words: [10, 25, 50, 100], time: [15, 30, 60, 120] } as const

export const CARETS = ['rainbow', 'red', 'blue', 'green', 'yellow', 'purple', 'orange', 'pink', 'cyan'] as const

export const DEFAULT_PREFS: Prefs = { kind: 'words', words: 25, time: 30, caret: 'rainbow' }

export const caretColor = (caret: string) => `${caret}_FOR_SUBAGENTS_ONLY`

export const tagOf = ({ kind, words, time }: Prefs) => `${kind}:${kind === 'words' ? words : time}`

export const LINE = 25
const FASTEST_CHARS_PER_MINUTE = 200 * 5

const WORDS = (
  'the be of and a to in he have it that for they with as not on she at by this we you do but from or which ' +
  'one would all will there say who make when can more if no man out other so what time up go about than into ' +
  'could state only new year some take come these know see use get like then first any work now may such give ' +
  'over think most even find day also after way many must look before great back through long where much should ' +
  'well people down own just because good each those feel seem how high too place little world very still nation ' +
  'hand old life tell write become here show house both between need mean call develop under last right move thing ' +
  'general school never same another begin while number part turn real leave might want point form off child few ' +
  'small since against ask late home interest large person end open public follow during present without again ' +
  'hold govern around possible head consider word program problem however lead system set order eye plan run keep ' +
  'face fact group play stand increase early course change help line'
).split(' ')

const randomWord = () => WORDS[Math.floor(Math.random() * WORDS.length)] ?? 'the'

export const deal = (kind: Kind, size: number): string[] => {
  if (kind === 'words') {
    return Array.from({ length: size }, randomWord)
  }

  const words: string[] = []
  let chars = 0

  while (chars < (size / 60) * FASTEST_CHARS_PER_MINUTE) {
    const word = randomWord()
    words.push(word)
    chars += word.length + 1
  }

  return [...words, ...Array.from({ length: LINE }, randomWord)]
}

