import type { ClientKeyEvent, ClientSurface } from 'claude-code'

import type { BoardProps, Kind } from '../types'
import { LINE, caretColor, deal } from './options.ts'

const RAINBOW = ['#eb5f57', '#f0883e', '#f5c242', '#7cc860', '#4fb0c6', '#5b8def', '#a46fd8', '#d66cb8']

type State = {
  id: string
  kind: Kind
  size: number
  words: string[]
  typed: string
  ms: number
  frame: number
  isStarted: boolean
  isDone: boolean
  isRecord: boolean
}
type Run = { text: string; color?: string; dimColor?: true; bold?: true; underline?: true; strikethrough?: true }

const fresh = (kind: Kind, size: number): State => ({
  id: Math.random().toString(36).slice(2),
  kind,
  size,
  words: deal(kind, size),
  typed: '',
  ms: 0,
  frame: 0,
  isStarted: false,
  isDone: false,
  isRecord: false,
})

const isFinished = (words: string[], typed: string): boolean => {
  const typedWords = typed.split(' ')

  return (
    typedWords.length > words.length ||
    (typedWords.length === words.length && (typedWords.at(-1) ?? '').length >= (words.at(-1) ?? '').length)
  )
}

const typedAfter = (typed: string, { key, ctrl, meta }: ClientKeyEvent): string | undefined => {
  const isErase = key === 'backspace' || key === 'delete'

  if ((isErase && meta) || (key === 'w' && ctrl)) {
    return typed.replace(/\S*\s?$/, '')
  }

  if (isErase) {
    return typed.slice(0, -1)
  }

  const char = key === 'space' ? ' ' : key

  return ctrl || meta || [...char].length !== 1 || char < ' ' ? undefined : typed + char
}

const score = ({ words, typed, ms }: State) => {
  const typedWords = typed.split(' ')
  let correctChars = 0
  let typedChars = 0
  let rightChars = 0

  words.forEach((word, i) => {
    const attempt = typedWords[i] ?? ''

    if (attempt === word) {
      correctChars += word.length + (i < words.length - 1 ? 1 : 0)
    }

    typedChars += attempt.length
    rightChars += [...attempt].filter((char, j) => char === word[j]).length
  })

  return {
    wpm: Math.round(correctChars / 5 / (Math.max(ms, 1) / 60000)),
    accuracy: typedChars === 0 ? 0 : Math.round((rightChars / typedChars) * 100),
  }
}

const runsOf = ({ words, typed, isDone }: State, from: number, to: number, caretStyle: { color?: string }): Run[] => {
  const typedWords = typed.split(' ')
  const active = typedWords.length - 1
  const caret = { ...caretStyle, bold: true, underline: true } as const
  const runs: Run[] = []
  const push = (run: Run) => {
    const last = runs.at(-1)
    const isSameStyle =
      last !== undefined &&
      last.color === run.color &&
      last.dimColor === run.dimColor &&
      last.bold === run.bold &&
      last.underline === run.underline &&
      last.strikethrough === run.strikethrough

    if (isSameStyle) {
      last.text += run.text
    } else {
      runs.push(run)
    }
  }

  words.slice(from, to).forEach((word, offset) => {
    const i = from + offset
    const attempt = typedWords[i]

    ;[...word].forEach((char, j) => {
      if (attempt === undefined || j >= attempt.length) {
        const isCaret = i === active && j === (attempt ?? '').length && !isDone

        return push(isCaret ? { text: char, ...caret } : { text: char, dimColor: true })
      }

      push(attempt[j] === char ? { text: char } : { text: char, color: 'red' })
    })

    if (attempt !== undefined && attempt.length > word.length) {
      push({ text: attempt.slice(word.length), color: 'red', strikethrough: true })
    }

    if (i < words.length - 1) {
      push(i === active && attempt === word && !isDone ? { text: ' ', ...caret } : { text: ' ', dimColor: true })
    }
  })

  return runs
}

export default function Board(props: BoardProps | undefined, surface: ClientSurface<State>) {
  const { Box, Text } = surface.elements
  const finish = (s: State) =>
    surface.post({ id: s.id, mode: `${s.kind}:${s.size}`, ...score(s), seconds: s.ms / 1000 })

  if (surface.state === undefined) {
    surface.setState(fresh(props?.kind ?? 'words', props?.size ?? LINE))
    surface.every(100, () => {
      const s = surface.state

      if (s === undefined || (s.isDone && !s.isRecord)) {
        return
      }

      const ms = s.isStarted && !s.isDone ? s.ms + 100 : s.ms
      const isTimeUp = s.kind === 'time' && !s.isDone && ms >= s.size * 1000
      const next = { ...s, frame: s.frame + 1, ms, isDone: s.isDone || isTimeUp }
      surface.setState(next)

      if (isTimeUp) {
        finish(next)
      }
    })
    surface.onKey(event => {
      const s = surface.state

      if (s === undefined) {
        return
      }

      if (event.key === 'tab' || (event.key === 'return' && s.isDone)) {
        return surface.setState(fresh(s.kind, s.size))
      }

      const typed = s.isDone ? undefined : typedAfter(s.typed, event)

      if (typed !== undefined && typed !== s.typed) {
        const next = { ...s, typed, isStarted: true, isDone: s.kind === 'words' && isFinished(s.words, typed) }
        surface.setState(next)

        if (next.isDone) {
          finish(next)
        }
      }
    })
  }

  const s = surface.state

  if (s === undefined) {
    return <Text dimColor>monkey</Text>
  }

  const { wpm, accuracy } = score(s)
  const seconds = (s.ms / 1000).toFixed(1)
  const record = s.isDone && props?.record?.id === s.id ? props.record : null
  const best = props?.best ?? null

  if (record !== null && !s.isRecord) {
    surface.setState({ ...s, isRecord: true })
  }

  const wave = (text: string) =>
    [...text].map((char, i) => (
      <Text color={RAINBOW[(((i - s.frame) % RAINBOW.length) + RAINBOW.length) % RAINBOW.length]}>{char}</Text>
    ))

  const caret = props?.caret ?? 'rainbow'
  const caretStyle = { color: caret === 'rainbow' ? RAINBOW[s.frame % RAINBOW.length] : caretColor(caret) }
  const done = Math.min(s.typed.split(' ').length - 1, s.words.length)
  const start = Math.floor(Math.min(done, s.words.length - 1) / LINE) * LINE
  const lines = [start, start + LINE].filter(from => from < s.words.length)
  const progress =
    s.kind === 'words' ? `${done}/${s.size}` : `${Math.max(0, Math.ceil(s.size - s.ms / 1000))}s left`
  const status = s.isDone
    ? `${accuracy}% acc · ${seconds}s · Enter or Tab: next · Esc: back to prompt`
    : s.isStarted
      ? `${progress} · Tab: new words`
      : `${progress} · click here, then type · Tab: new words · Esc: back to prompt`

  return (
    <Box flexDirection="column">
      {lines.map(from => (
        <Text wrap="wrap">
          {s.isRecord
            ? wave(s.words.slice(from, from + LINE).join(' '))
            : runsOf(s, from, from + LINE, caretStyle).map(({ text, ...style }) => <Text {...style}>{text}</Text>)}
        </Text>
      ))}
      {record !== null && (
        <Text bold>
          {wave(`★ New record! ${wpm} WPM${record.previous === null ? '' : `, up from ${record.previous}`} ★`)}
        </Text>
      )}
      <Box>
        {s.isDone && record === null && (
          <Text bold color="yellow">
            {wpm} WPM{'  '}
          </Text>
        )}
        <Text dimColor>
          {status}
          {best === null ? '' : ` · best ${best} WPM`}
        </Text>
      </Box>
    </Box>
  )
}

