export type Round = number | null

export type Kind = 'words' | 'time'

export type Prefs = { kind: Kind; words: number; time: number; caret: string }

export type Finished = { id: string; mode: string; wpm: number; accuracy: number; seconds: number }

export type Run = Omit<Finished, 'id'> & { at: number }

export type NewRecord = { id: string; previous: number | null }

export type BoardProps = { kind: Kind; size: number; caret: string; best: number | null; record: NewRecord | null }

declare module 'claude-code' {
  interface PluginState {
    monkey: { round: Round; best: number | null; record: NewRecord | null; prefs: Prefs }
  }
}
